        self.calls = 0

    def GetProperty(self, *_args):
        if self.calls < len(self.operations):
            mode, payload = self.operations[self.calls]
        else:
            mode, payload = ("atoms", [9109])
        self.calls += 1
        return _DummyPropertyCookie(mode, payload)


